mapper.select:
SELECT  
FROM message_records 
WHERE status = 2 AND retry_count < #{maxRetry}
ORDER BY update_time ASC
LIMIT #{limit}

mapper.update:
UPDATE message_records 
SET status = #{status}, error_msg = #{errorMsg}, update_time = NOW()
WHERE id = #{id}

UPDATE message_records 
SET retry_count = retry_count + 1, update_time = NOW()
WHERE id = #{id}

UPDATE message_records 
SET status = 3, update_time = NOW()
WHERE business_id = #{businessId} AND message_type = #{messageType}
